  World := { w | w = r ∨ r ≺ w }
  Rel x y := x.1 ≺ y.1
  world_nonempty := ⟨r, by tauto⟩
  root := ⟨r, by tauto⟩
  root_rooted := by
    rintro ⟨x, (rfl | hx)⟩;
    . intro h; contradiction;
    . intro _; exact hx;

