  atomic := by
    intro x₁ x₂ a e; subst e;
    constructor;
    . apply f.atomic.mp;
    . apply f.atomic.mpr;
  forth := by
    simp;
    intro x₁ y₁ rx₁y₁;
    exact f.forth rx₁y₁;
  back := by
    simp;
    intro x₁ x₂ y₂ e rx₂y₂; subst e;
    obtain ⟨y₁, _⟩ := f.back rx₂y₂;
    use y₁;
}

