    obtain ⟨y, ⟨hyz, hxy⟩⟩ := g.back hxw;
    obtain ⟨u, ⟨hgu, hfu⟩⟩ := f.back hxy;
    use u;
    constructor;
    . subst_vars; simp;
    . assumption;

